   501→// isInstalledWithHookSupport returns true if the agent is installed (binary in PATH)
   502→// and implements HookSupport, so we can install hooks for it.
   503→// Returns (false, err) when IsInstalled() returns an unexpected OS error, so callers
   504→// can propagate it instead of showing a generic "not found" message.
   505→func isInstalledWithHookSupport(ag agent.Agent) (bool, error) {
   506→	if _, ok := ag.(agent.HookSupport); !ok {
   507→		return false, nil
   508→	}
   509→	installed, err := ag.IsInstalled()
   510→	if err != nil {
   511→		return false, fmt.Errorf("checking installation status: %w", err)
   512→	}
   513→	return installed, nil
   514→}
   515→
   516→// findInstalledAgent returns the first installed agent that supports hooks.
   517→// It tries the default agent first, then checks all registered agents.
   518→// Only agents that are both installed (binary in PATH) and implement HookSupport
   519→// are returned, so the enable flow can always install hooks.
   520→// Returns the agent and nil error if found, or nil agent and an error with
   521→// helpful install instructions written to errW (stderr). OS errors from
   522→// IsInstalled() (e.g. permission errors on PATH) are propagated to the caller.
   523→func findInstalledAgent(errW io.Writer) (agent.Agent, error) {
   524→	var firstErr error
   525→
   526→	// Try the default agent first
   527→	ag := agent.Default()
   528→	if ag != nil {
   529→		ok, err := isInstalledWithHookSupport(ag)
   530→		if err != nil {
   531→			firstErr = err
   532→		} else if ok {
   533→			return ag, nil
   534→		}
   535→	}
   536→
   537→	// Check all registered agents
   538→	for _, name := range agent.List() {
   539→		a, err := agent.Get(name)
   540→		if err != nil {
   541→			continue
   542→		}
   543→		ok, err := isInstalledWithHookSupport(a)
   544→		if err != nil {
   545→			if firstErr == nil {
   546→				firstErr = err
   547→			}
   548→		} else if ok {
   549→			return a, nil
   550→		}
   551→	}
   552→
   553→	// If we hit an OS error while checking, propagate it
   554→	if firstErr != nil {
   555→		return nil, fmt.Errorf("error checking if agent is installed: %w", firstErr)
   556→	}
   557→
   558→	// No hook-supporting agents found - provide helpful error to stderr
   559→	fmt.Fprintln(errW, "No AI agents with hook support found in PATH.")
   560→	fmt.Fprintln(errW)
   561→	fmt.Fprintln(errW, "Please install one of the following:")
   562→	for _, name := range agent.List() {
   563→		a, err := agent.Get(name)
   564→		if err != nil {
   565→			continue
   566→		}
   567→		fmt.Fprintf(errW, "  - %s: %s\n", a.Description(), a.InstallURL())
   568→	}
   569→	return nil, NewSilentError(errors.New("no agents installed"))
   570→}
