   229→func runEnableWithStrategy(w, errW io.Writer, selectedStrategy string, localDev, _, useLocalSettings, useProjectSettings, forceHooks, skipPushSessions, telemetry bool) error {
   230→	// Map the strategy to internal name if it's a display name
   231→	internalStrategy := selectedStrategy
   232→	if mapped, ok := strategyDisplayToInternal[selectedStrategy]; ok {
   233→		internalStrategy = mapped
