   247→	fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", ag.Type())
   248→
   249→	// Setup agent hooks (agent hooks don't depend on settings)
   250→	if _, err := setupAgentHooks(ag, localDev, forceHooks); err != nil {
