   256→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   257→	}
   258→
   259→	// Load existing settings to preserve other options (like strategy_options.push)
   260→	settings, err := LoadEntireSettings()
   261→	if err != nil {
   262→		// If we can't load, start with defaults
   263→		settings = &EntireSettings{}
   264→	}
   265→	// Update the specific fields
   266→	settings.Strategy = internalStrategy
   267→	settings.LocalDev = localDev
   268→	settings.Enabled = true
   269→
   270→	// Set push_sessions option if --skip-push-sessions flag was provided
   271→	if skipPushSessions {
   272→		if settings.StrategyOptions == nil {
   273→			settings.StrategyOptions = make(map[string]interface{})
   274→		}
   275→		settings.StrategyOptions["push_sessions"] = false
   276→	}
