   278→	// Handle telemetry for non-interactive mode
   279→	// Note: if telemetry is nil (not configured), it defaults to disabled
   280→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   281→		f := false
