   290→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   291→
   292→	if showNotification {
   293→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
   294→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
   295→	}
